240	    @Override
241	    @Transactional
242	    public void saveOwner(Owner owner) throws DataAccessException {
243	        if (owner.getTelephone() != null) {
244	            owner.setTelephone(normalizeTelephone(owner.getTelephone()));
245	        }
246	        if (owner.getEmail() != null) {
247	            owner.setEmail(normalizeEmail(owner.getEmail()));
248	        }
249	        if (owner.getAddress() != null) {
250	            owner.setAddress(normalizeAddress(owner.getAddress()));
251	        }
252	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
253	        owner.setRegistrationDate(rollToBusinessDay(effectiveDate));
254	        if (owner.getCustomerCode() == null) {
255	            owner.setCustomerCode(generateCustomerCode(owner));
256	        }
257	        if (owner.isNew()) {
258	            owner.setNamesakeCount(countNamesakes(owner));
259	            assertDailyCapacity(owner);
260	            assertCityCapacity(owner);
261	        }
262	        assertTelephoneUnique(owner, owner.getTelephone());
263	        List<Owner> household = findHouseholdMembers(owner);
264	        assertHouseholdAllowed(owner, household);
265	        assignHousehold(owner, household);
266	        ownerRepository.save(owner);
267	    }
268	
269	    /**
270	     * Build a {@code customerCode} formatted {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is the
271	     * upper-cased first three letters of the owner's city, LAST3 the upper-cased first three
272	     * letters of {@code lastName}, and NNNN is a per-city 4-digit zero-padded sequence equal to
273	     * one more than the number of owners already in that city.
274	     */
275	    private String generateCustomerCode(Owner owner) {
276	        String cityPrefix = prefix3(owner.getCity());
277	        String lastNamePrefix = prefix3(owner.getLastName());
278	        long sequence = countOwnersInCity(owner.getCity()) + 1L;
279	        return String.format("%s-%s-%04d", cityPrefix, lastNamePrefix, sequence);
280	    }
281	
282	    private static String prefix3(String value) {
283	        return value.substring(0, Math.min(3, value.length())).toUpperCase(Locale.ROOT);
284	    }
285	
286	    /** Maximum number of owners permitted in a single city. */
287	    private static final long CITY_OWNER_LIMIT = 50L;
288	
289	    /**
290	     * Rejects creating {@code owner} when its city already contains {@link #CITY_OWNER_LIMIT} or
291	     * more owners, so no city can grow beyond the capacity limit.
292	     *
293	     * @throws CityOwnerLimitException if the owner's city is already at capacity
294	     */
295	    private void assertCityCapacity(Owner owner) {
296	        if (owner.getCity() == null) {
297	            return;
298	        }
299	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
300	            throw new CityOwnerLimitException(owner.getCity(), CITY_OWNER_LIMIT);
301	        }
302	    }
303	
304	    /**
305	     * Rolls {@code date} forward to the next business day when it falls on a weekend: a Saturday or
306	     * Sunday becomes the following Monday. Business days (Monday to Friday) are returned unchanged.
307	     */
308	    private static LocalDate rollToBusinessDay(LocalDate date) {
309	        switch (date.getDayOfWeek()) {
310	            case SATURDAY:
311	                return date.plusDays(2);
312	            case SUNDAY:
313	                return date.plusDays(1);
314	            default:
315	                return date;
316	        }
317	    }
318	
319	    /** Maximum number of owners permitted to be registered on a single day. */
320	    private static final long DAILY_OWNER_LIMIT = 100L;
321	
322	    /**
323	     * Rejects creating {@code owner} when its {@code registrationDate} (defaulted to today for a new
324	     * owner) already has {@link #DAILY_OWNER_LIMIT} or more owners registered, so no more than that
325	     * many owners can be created on any single day.
326	     *
327	     * @throws DailyOwnerLimitException if the owner's registration day is already at capacity
328	     */
329	    private void assertDailyCapacity(Owner owner) {
330	        LocalDate date = owner.getRegistrationDate();
331	        if (date == null) {
332	            return;
333	        }
334	        if (countOwnersRegisteredOn(date) >= DAILY_OWNER_LIMIT) {
335	            throw new DailyOwnerLimitException(date, DAILY_OWNER_LIMIT);
336	        }
337	    }
338	
339	    private long countOwnersRegisteredOn(LocalDate date) {
340	        return ownerRepository.findAll().stream()
341	                .filter(existing -> date.equals(existing.getRegistrationDate()))
342	                .count();
343	    }
344	
345	    private long countOwnersInCity(String city) {
346	        String normalized = normalizeHouseholdValue(city);
347	        return ownerRepository.findAll().stream()
348	                .filter(existing -> normalized.equals(normalizeHouseholdValue(existing.getCity())))
349	                .count();
350	    }
351	
352	    /**
353	     * Counts the existing owners that share both {@code firstName} and {@code lastName} with the
354	     * given new {@code owner}, compared case-insensitively (with incidental whitespace collapsed).
355	     * The owner being created is not itself persisted yet, so the result is the number of namesakes
356	     * that already existed before this create.
357	     */
358	    private int countNamesakes(Owner owner) {
359	        String firstName = normalizeHouseholdValue(owner.getFirstName());
360	        String lastName = normalizeHouseholdValue(owner.getLastName());
361	        int count = 0;
362	        for (Owner existing : ownerRepository.findAll()) {
363	            if (!existing.getId().equals(owner.getId())
364	                    && firstName.equals(normalizeHouseholdValue(existing.getFirstName()))
365	                    && lastName.equals(normalizeHouseholdValue(existing.getLastName()))) {
366	                count++;
367	            }
368	        }
369	        return count;
370	    }
371	
372	    private static String normalizeEmail(String email) {
373	        return email == null ? null : email.toLowerCase(Locale.ROOT);
374	    }
375	
376	    /** Common street-type abbreviations expanded during address normalization. */
377	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
378	        "ST", "STREET",
379	        "RD", "ROAD",
380	        "AVE", "AVENUE");
381	
382	    /**
383	     * Canonicalizes a postal address: trims and collapses runs of whitespace into a single space,
384	     * upper-cases, and expands common street-type abbreviations (ST->STREET, RD->ROAD, AVE->AVENUE)
385	     * as whole words. Returns {@code null} for a {@code null} input and an empty string when the
386	     * address is blank once whitespace is stripped, so the required-field check sees the normalized
387	     * form.
388	     */
389	    private static String normalizeAddress(String address) {
390	        if (address == null) {
391	            return null;
392	        }
393	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
394	        if (collapsed.isEmpty()) {
395	            return "";
396	        }
397	        String[] tokens = collapsed.split(" ");
398	        StringBuilder sb = new StringBuilder(collapsed.length());
399	        for (int i = 0; i < tokens.length; i++) {
400	            if (i > 0) {
401	                sb.append(' ');
402	            }
403	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
404	        }
405	        return sb.toString();
406	    }
407	
408	    private static String normalizeTelephone(String telephone) {
409	        return telephone == null ? null : E164Telephone.toE164(telephone);
410	    }
411	
412	    /**
413	     * Rejects saving {@code owner} when its {@code normalized} telephone is already used by any
414	     * other owner, so no two owners can share a telephone number.
415	     *
416	     * @throws DuplicateTelephoneException if another owner already has the same normalized telephone
417	     */
418	    private void assertTelephoneUnique(Owner owner, String normalized) {
419	        if (normalized == null || normalized.isEmpty()) {
420	            return;
421	        }
422	        for (Owner existing : ownerRepository.findAll()) {
423	            if (!existing.getId().equals(owner.getId())
424	                    && normalized.equals(normalizeTelephone(existing.getTelephone()))) {
425	                throw new DuplicateTelephoneException(normalized);
426	            }
427	        }
428	    }
429	
430	    /**
431	     * Returns the existing owners that share both {@code lastName} (compared case-insensitively with
432	     * collapsed whitespace) and the normalized {@code address} with a new {@code owner} — i.e. the
433	     * members of the household it would join. Returns an empty list for an update to an existing
434	     * owner or when either household value is blank, so household rules only apply to genuine new
435	     * members.
436	     */
437	    private List<Owner> findHouseholdMembers(Owner owner) {
438	        if (!owner.isNew()) {
439	            return List.of();
440	        }
441	        String lastName = normalizeHouseholdValue(owner.getLastName());
442	        String address = normalizeHouseholdAddress(owner.getAddress());
443	        if (lastName.isEmpty() || address.isEmpty()) {
444	            return List.of();
445	        }
446	        List<Owner> household = new ArrayList<>();
447	        for (Owner existing : ownerRepository.findAll()) {
448	            if (!existing.getId().equals(owner.getId())
449	                    && lastName.equals(normalizeHouseholdValue(existing.getLastName()))
450	                    && address.equals(normalizeHouseholdAddress(existing.getAddress()))) {
451	                household.add(existing);
452	            }
453	        }
454	        return household;
455	    }
456	
457	    /**
458	     * Pure guard: rejects creating {@code owner} when it would join a non-empty {@code household}
459	     * without acknowledging the shared household via {@link Owner#isSharesHousehold()}. Returns
460	     * without side effects otherwise.
461	     *
462	     * @throws DuplicateHouseholdException if another owner already lives at the same household and
463	     *                                     the request does not acknowledge the shared household
464	     */
465	    private void assertHouseholdAllowed(Owner owner, List<Owner> household) {
466	        if (!household.isEmpty() && !owner.isSharesHousehold()) {
467	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
468	        }
469	    }
470	
471	    /**
472	     * Assigns household membership when {@code owner} joins a non-empty {@code household}: the new
473	     * owner and every matching existing member that lacks one are given the same stable
474	     * {@code householdId}, and any updated existing members are persisted. No-op when the household
475	     * is empty.
476	     */
477	    private void assignHousehold(Owner owner, List<Owner> household) {
478	        if (household.isEmpty()) {
479	            return;
480	        }
481	        String householdId = resolveHouseholdId(owner, household);
482	        owner.setHouseholdId(householdId);
483	        for (Owner existing : household) {
484	            if (existing.getHouseholdId() == null || existing.getHouseholdId().isBlank()) {
485	                existing.setHouseholdId(householdId);
486	                ownerRepository.save(existing);
487	            }
488	        }
489	    }
490	
491	    /**
492	     * Returns the {@code householdId} shared by a household: the first non-blank identifier already
493	     * carried by an existing member, or otherwise a freshly derived stable identifier for the
494	     * joining {@code owner}'s normalized lastName and address.
495	     */
496	    private String resolveHouseholdId(Owner owner, List<Owner> household) {
497	        for (Owner existing : household) {
498	            if (existing.getHouseholdId() != null && !existing.getHouseholdId().isBlank()) {
499	                return existing.getHouseholdId();
500	            }
501	        }
502	        return generateHouseholdId(normalizeHouseholdValue(owner.getLastName()),
503	            normalizeHouseholdAddress(owner.getAddress()));
504	    }
505	
506	    /**
507	     * Derives a stable {@code householdId} formatted {@code 'HH-<12 upper-hex>'} from the SHA-256
508	     * digest of the normalized {@code lastName} and {@code address}, so all owners in the same
509	     * household deterministically share the same identifier.
510	     */
511	    private static String generateHouseholdId(String lastName, String address) {
512	        try {
513	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
514	            byte[] hash = digest.digest((lastName + "\u0000" + address).getBytes(StandardCharsets.UTF_8));
515	            StringBuilder sb = new StringBuilder();
516	            for (int i = 0; i < 6; i++) {
517	                sb.append(String.format("%02X", hash[i]));
518	            }
519	            return "HH-" + sb;
520	        } catch (NoSuchAlgorithmException e) {
521	            throw new IllegalStateException("SHA-256 not available", e);
522	        }
523	    }
524	
525	    /**
526	     * Normalizes a household comparison value by trimming, collapsing runs of whitespace into a
527	     * single space and lower-casing, so comparisons ignore case and incidental whitespace.
528	     */
529	    private static String normalizeHouseholdValue(String value) {
530	        if (value == null) {
531	            return "";
532	        }
533	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
534	    }
535	
536	    /**
537	     * Household comparison value for an address: the canonical {@link #normalizeAddress(String)}
538	     * form (never {@code null}), so duplicate detection and the shared household id compare
539	     * addresses using the same normalized representation that is stored and returned.
540	     */
541	    private static String normalizeHouseholdAddress(String address) {
542	        String normalized = normalizeAddress(address);
543	        return normalized == null ? "" : normalized;
544	    }
545	
546	    @Override
547	    @Transactional(readOnly = true)
548	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
549	        return ownerRepository.findByLastName(lastName);
550	    }
551	
552	    @Override
553	    @Transactional(readOnly = true)
554	    public Collection<Visit> findVisitsByPetId(int petId) {
555	        return visitRepository.findByPetId(petId);
556	    }
557	
558	    @Override
559	    @Transactional(readOnly = true)
560	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
561	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
562	    }
563	
564	    private <T> T findEntityById(Supplier<T> supplier) {
565	        try {
566	            return supplier.get();
567	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
568	            // Just ignore not found exceptions for Jdbc/Jpa realization
569	            return null;
570	        }
571	    }
572	
573	}
